        in = 8'hFF; #10;
        expected = 8'hFF;
        if (out !== expected) errors = errors + 1;

        // Test asymmetric patterns
        in = 8'b10000000; #10; // MSB set
        expected = 8'b00000001; // Should be LSB set
        if (out !== expected) errors = errors + 1;

        in = 8'b00000001; #10; // LSB set
        expected = 8'b10000000; // Should be MSB set
        if (out !== expected) errors = errors + 1;

