            if (out !== expected) begin
                errors = errors + 1;
            end
        end

        // Final result check
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
